import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import path from 'node:path';import os from 'node:os';import {createCanvasBackend} from '../../../lib/canvas/runtime-host.mjs';
async function setup(){const temp=await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(),'dsh-canvas-test-'))),library=path.join(temp,'shared');await fs.mkdir(library);const originals=[];const assets={list:async()=>originals,get:async id=>originals.find(a=>a.id===id||a.path===id||a.aliases?.includes(id))||null,ingestFile:async(file,options)=>{const existing=originals.find(a=>a.path===file);if(existing)return existing;const value={id:'canonical-'+originals.length,path:file,kind:'image',aliases:[options?.alias].filter(Boolean)};originals.push(value);return value;},addReference:async()=>{}};const backend=createCanvasBackend({rootDir:path.join(temp,'project'),assets,models:{invoke:async c=>({command:c})}});await backend.invoke('canvas_bootstrap');return{temp,library,backend,assets,originals,cleanup:async()=>{await backend.dispose();await fs.rm(temp,{recursive:true,force:true});}};}
test('real atomic file and project receipt survive a new backend',async()=>{const t=await setup();try{const{cacheDirectory}=await t.backend.invoke('canvas_bootstrap'),file=path.join(cacheDirectory,'project management','document-1','payload.json');await t.backend.invoke('write_text_file_atomic',{path:file,body:JSON.stringify({nodes:[],connections:[],groups:[]})});const receipt=await t.backend.invoke('canvas_save_receipt',{documentRef:'project:document-1',snapshot:{nodes:[]}}, {projectId:'dsh-project'});assert.equal(receipt.projectId,'dsh-project');assert.equal(receipt.bytes,(await fs.stat(file)).size);assert.match(receipt.sha256,/^[a-f0-9]{64}$/);await t.backend.dispose();const b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:t.assets});assert.match(Buffer.from(await b.invoke('plugin:fs|read_file',{path:file})).toString(),/nodes/);await b.dispose();}finally{await t.cleanup();}});
test('shared originals are readable but cannot be overwritten/deleted; symlink escape rejected',async()=>{const t=await setup();try{const original=path.join(t.library,'original.png');await fs.writeFile(original,'actual original');t.originals.push({id:'canonical',path:original});assert.equal(Buffer.from(await t.backend.invoke('read_file_bytes',{path:original})).toString(),'actual original');await assert.rejects(t.backend.invoke('plugin:fs|remove',{path:original}),/outside owned/);await assert.rejects(t.backend.invoke('plugin:fs|write_file',{path:original,__raw:[1]}),/outside owned/);await fs.symlink(t.library,path.join(t.temp,'project','escape'));await assert.rejects(t.backend.invoke('plugin:fs|write_file',{path:path.join(t.temp,'project','escape','bad.txt'),__raw:[1]}),/symbolic link/);assert.equal(await fs.readFile(original,'utf8'),'actual original');}finally{await t.cleanup();}});
test('manifest sqlite connections stay independent across project backends',async()=>{const t=await setup(),b=createCanvasBackend({rootDir:path.join(t.temp,'other'),assets:t.assets});try{await t.backend.invoke('manifest_db_open');await b.invoke('manifest_db_open');await t.backend.invoke('manifest_db_set_meta',{key:'owner',value:'A'});await b.invoke('manifest_db_set_meta',{key:'owner',value:'B'});assert.equal(await t.backend.invoke('manifest_db_get_meta',{key:'owner'}),'A');assert.equal(await b.invoke('manifest_db_get_meta',{key:'owner'}),'B');}finally{await b.dispose();await t.cleanup();}});
test('imports go through the single asset gateway and unsupported commands fail',async()=>{const t=await setup();try{const file=path.join(t.temp,'project','result.png');await t.backend.invoke('write_bytes_to_file',{path:file,bytes:[1,2,3]});const imported=await t.backend.invoke('aiyouplus_local_import',{inputPaths:[file]},{projectId:'p'});assert.equal(imported[0].id,'canonical-0');assert.equal((await t.backend.invoke('aiyouplus_local_assets'))[0].path,file);await assert.rejects(t.backend.invoke('run_local_skill_command',{command:'echo must-not-run'}),/Unsupported/);await assert.rejects(t.backend.invoke('proxy_fetch_raw',{url:'https://example.com'}),/Unsupported/);}finally{await t.cleanup();}});
test('reference staging is registered before host model invocation, with canonical original paths',async()=>{const t=await setup();let captured;try{const staged=path.join(t.temp,'project','tmp','reference.png'),canonical=path.join(t.library,'canonical.png');await t.backend.invoke('write_bytes_to_file',{path:staged,bytes:[137,80,78,71]});const assets={...t.assets,ingestFile:async(file,options)=>{assert.ok(file.startsWith(path.join(t.temp,'project')));await fs.copyFile(file,canonical);return{id:'canonical-reference',path:canonical,aliases:[]};}};const b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets,models:{invoke:async(command,args)=>{captured={command,args};return{requestId:'fixture-no-network'};}}});await b.invoke('aiyouplus_model_generate',{kind:'image',model:'fixture',requestId:'r1',referencePaths:[staged]},{projectId:'p'});assert.deepEqual(captured.args.referencePaths,[canonical]);await assert.rejects(b.invoke('aiyouplus_model_generate',{referencePaths:[path.join(t.temp,'not-authorized.png')]}),/neither owned/);await b.dispose();}finally{await t.cleanup();}});
test('multi-import derives stable per-item idempotency keys',async()=>{const t=await setup(),keys=[];try{const a=path.join(t.temp,'project','a.png'),b=path.join(t.temp,'project','b.png');await fs.writeFile(a,'A');await fs.writeFile(b,'B');const runtime=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:{...t.assets,ingestFile:async(file,options)=>{keys.push(options.requestId);return{id:file,path:file};}}});await runtime.invoke('aiyouplus_local_import',{inputPaths:[a,b]},{requestId:'request'});assert.deepEqual(keys,['request:0','request:1']);await runtime.dispose();}finally{await t.cleanup();}});
test('production RPC preserves method and positional args at the host boundary',async()=>{const t=await setup();let actual;const b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:t.assets,host:{production:async args=>{actual=args;return{recipes:[]};}}});try{assert.deepEqual(await b.invoke('canvas_production',{method:'snapshot',args:[]}),{recipes:[]});assert.deepEqual(actual,{method:'snapshot',args:[]});}finally{await b.dispose();await t.cleanup();}});
test('browser uploads constrain names, offsets, declared size and owning project/session',async()=>{const t=await setup(),c={projectId:'p',sessionId:'s'};try{await assert.rejects(t.backend.invoke('canvas_upload_begin',{name:'../escape.zip',size:1},c),/filename/);await assert.rejects(t.backend.invoke('canvas_upload_begin',{name:'valid.zip',size:513*1024*1024},c),/512/);const begin=await t.backend.invoke('canvas_upload_begin',{name:'project.zip',size:5},c);await assert.rejects(t.backend.invoke('canvas_upload_chunk',{uploadId:begin.uploadId,offset:0,dataBase64:'YQ=='},{projectId:'other'}),/another project/);await assert.rejects(t.backend.invoke('canvas_upload_chunk',{uploadId:begin.uploadId,offset:1,dataBase64:'YQ=='},c),/offset/);await assert.rejects(t.backend.invoke('canvas_upload_complete',{uploadId:begin.uploadId},c),/incomplete/);await t.backend.invoke('canvas_upload_chunk',{uploadId:begin.uploadId,offset:0,dataBase64:Buffer.from('hello').toString('base64')},c);const completed=await t.backend.invoke('canvas_upload_complete',{uploadId:begin.uploadId},c);assert.match(completed.path,/tmp\/browser-uploads\/[a-f0-9-]{36}\/project.zip$/);assert.equal(await fs.readFile(completed.path,'utf8'),'hello');assert.equal(completed.bytes,5);await assert.rejects(t.backend.invoke('canvas_upload_chunk',{uploadId:begin.uploadId,offset:5,dataBase64:'YQ=='},c),/closed/);}finally{await t.cleanup();}});
test('browser exports become downloadable only after actual complete file bytes exist',async()=>{const t=await setup(),c={projectId:'p',sessionId:'s'};try{const target=await t.backend.invoke('canvas_export_begin',{name:'actual.zip'},c);await assert.rejects(t.backend.invoke('canvas_export_stat',{exportId:target.exportId},c),/ENOENT/);const data=Buffer.from('actual archive fixture bytes'),u=await t.backend.invoke('canvas_upload_begin',{name:'actual.zip',size:data.length},c);await t.backend.invoke('canvas_upload_chunk',{uploadId:u.uploadId,offset:0,dataBase64:data.toString('base64')},c);await t.backend.invoke('canvas_upload_complete',{uploadId:u.uploadId},c);const out=await t.backend.invoke('canvas_export_commit',{uploadId:u.uploadId,exportId:target.exportId},c);assert.equal(out.bytes,data.length);assert.deepEqual(await fs.readFile(out.path),data);assert.equal((await t.backend.invoke('canvas_list_exports',{},c))[0].path,out.path);await t.backend.invoke('canvas_upload_cancel',{uploadId:u.uploadId},c);assert.deepEqual(await fs.readFile(out.path),data);await assert.rejects(t.backend.invoke('canvas_export_stat',{exportId:target.exportId},{projectId:'wrong'}),/Unknown exportId/);}finally{await t.cleanup();}});
test('saving removes only this document references, migrates legacy slots, and protects another document',async()=>{const t=await setup(),references=new Set(),events=[],key=(id,o)=>JSON.stringify([id,o.projectId,o.nodeId,o.slot]),c={projectId:'dsh-project'};let b;try{const asset={id:'canonical',path:path.join(t.library,'asset.png')};await fs.writeFile(asset.path,'original');t.originals.push(asset);const linked={id:'same-node-id',settings:{_assetId:'canonical'}};const cache=t.backend.directories.cache;for(const name of ['doc-a','doc-b'])await t.backend.invoke('write_text_file_atomic',{path:path.join(cache,'project management',name,'payload.json'),body:JSON.stringify({nodes:[linked]})});references.add(key('canonical',{...c,nodeId:linked.id,slot:'canvas'}));b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:{...t.assets,addReference:async(id,o)=>{events.push(['add',o.slot]);references.add(key(id,o));},removeReference:async(id,o)=>{events.push(['remove',o.slot]);references.delete(key(id,o));}}});await b.invoke('canvas_save_receipt',{documentRef:'project:doc-a',snapshot:{nodes:[linked]}},c);assert.equal(references.size,2);assert.ok(!references.has(key('canonical',{...c,nodeId:linked.id,slot:'canvas'})));assert.equal(events.filter(e=>e[0]==='add').length,2);assert.equal(events.at(-1)[1],'canvas');await b.invoke('canvas_save_receipt',{documentRef:'project:doc-a',snapshot:{nodes:[]}},c);assert.deepEqual([...references],[key('canonical',{...c,nodeId:linked.id,slot:'canvas:project:doc-b'})]);await b.dispose();b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:{...t.assets,addReference:async(id,o)=>references.add(key(id,o)),removeReference:async(id,o)=>references.delete(key(id,o))}});await b.invoke('canvas_save_receipt',{documentRef:'project:doc-b',snapshot:{nodes:[]}},c);assert.equal(references.size,0);assert.equal(await fs.readFile(asset.path,'utf8'),'original');}finally{await b?.dispose();await t.cleanup();}});
test('project resource batch copy prevalidates every source and target',async()=>{const t=await setup();try{const source=path.join(t.library,'shared.bin');await fs.writeFile(source,'source bytes');t.originals.push({id:'shared',path:source});const dest=path.join(t.temp,'project','cache','original.bin');const result=await t.backend.invoke('copy_local_files_batch',{items:[{src:source,dest}]});assert.equal(result.succeeded,1);assert.equal(await fs.readFile(dest,'utf8'),'source bytes');const forbidden=path.join(t.library,'never-write.bin'),second=path.join(t.temp,'project','cache','should-not-exist.bin');await assert.rejects(t.backend.invoke('copy_local_files_batch',{items:[{src:source,dest:second},{src:source,dest:forbidden}]}),/outside owned/);await assert.rejects(fs.stat(second),/ENOENT/);await assert.rejects(fs.stat(forbidden),/ENOENT/);}finally{await t.cleanup();}});
test('reference arrays retain canonical ids and release after asset removal',async()=>{const t=await setup(),refs=new Set();let b;try{t.originals.push({id:'array-asset',path:path.join(t.library,'array.png')});await fs.writeFile(t.originals[0].path,'original');const pathA=path.join(t.backend.directories.cache,'project management','array-doc','payload.json');await t.backend.invoke('write_text_file_atomic',{path:pathA,body:'{"nodes":[]}'});b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:{...t.assets,addReference:async(id,o)=>refs.add(JSON.stringify([id,o.slot])),removeReference:async(id,o)=>refs.delete(JSON.stringify([id,o.slot]))}});await b.invoke('canvas_save_receipt',{documentRef:'project:array-doc',snapshot:{nodes:[{id:'n',referenceAssetIds:['array-asset']}]}});assert.deepEqual([...refs],[JSON.stringify(['array-asset','canvas:project:array-doc'])]);await b.invoke('canvas_save_receipt',{documentRef:'project:array-doc',snapshot:{nodes:[{id:'n',referenceAssetIds:[]}]}});assert.equal(refs.size,0);}finally{await b?.dispose();await t.cleanup();}});
test('asset gateway transport errors prevent a false successful save receipt',async()=>{const t=await setup();let b;try{await t.backend.invoke('write_text_file_atomic',{path:path.join(t.backend.directories.cache,'project management','offline-doc','payload.json'),body:'{"nodes":[]}'});b=createCanvasBackend({rootDir:path.join(t.temp,'project'),assets:{...t.assets,get:async()=>{throw Error('Gateway unavailable');}}});await assert.rejects(b.invoke('canvas_save_receipt',{documentRef:'project:offline-doc',snapshot:{nodes:[{id:'n',referenceAssetId:'canonical'}]}}),/Gateway unavailable/);await assert.rejects(fs.stat(path.join(t.temp,'project','last-document.json')),/ENOENT/);}finally{await b?.dispose();await t.cleanup();}});

test('browser uploads and export destinations stay scoped to their exact panel',async()=>{const t=await setup();try{const a={projectId:'p',sessionId:'s',panelId:'panel-a'},b={...a,panelId:'panel-b'},u=await t.backend.invoke('canvas_upload_begin',{name:'panel.txt',size:1},a);await assert.rejects(t.backend.invoke('canvas_upload_chunk',{uploadId:u.uploadId,offset:0,dataBase64:'QQ=='},b),/another project\/session\/panel/);await t.backend.invoke('canvas_upload_chunk',{uploadId:u.uploadId,offset:0,dataBase64:'QQ=='},a);const file=await t.backend.invoke('canvas_upload_complete',{uploadId:u.uploadId},a);assert.equal(await fs.readFile(file.path,'utf8'),'A');const destination=await t.backend.invoke('canvas_export_begin',{name:'panel.txt'},a);await assert.rejects(t.backend.invoke('canvas_export_commit',{exportId:destination.exportId,uploadId:u.uploadId},b),/this project\/session\/panel/);await t.backend.invoke('canvas_upload_cancel',{uploadId:u.uploadId},a);}finally{await t.cleanup();}});
